package world.gregs.voidps.tools.cache

import com.displee.cache.CacheLibrary
import com.fasterxml.jackson.module.kotlin.jacksonObjectMapper
import com.fasterxml.jackson.module.kotlin.readValue
import world.gregs.voidps.cache.CacheDelegate
import world.gregs.voidps.cache.Index
import world.gregs.voidps.cache.translation.CacheTranslationPatch
import world.gregs.voidps.cache.translation.CacheTranslationPatch.Source
import world.gregs.voidps.cache.translation.SkillGuideTranslation
import java.io.File
import java.net.ServerSocket
import kotlin.system.exitProcess

/**
 * Writes the Brazilian Portuguese of the interfaces the client draws from the cache (Task System, level up
 * pop-up), worked out by [CacheTranslationPatch].
 *
 * Usage (from the repository root, with the server stopped for `patch`):
 *   dump  - writes the English texts in scope without translation to tools/translation/sources/missing_interfaces.json
 *   table - writes interface_pt_br.tables.toml from tools/translation/sources/pt_tasks*.json and pt_level_up*.json,
 *           and skill_guide_pt_br.guide.toml from pt_guide*.json
 *   patch - applies both tables to the cache
 * `--cache <dir>` and `--table <file>` point at another cache or table, e.g. a copy to try a change on.
 */
object InterfaceTranslation {

    private const val SOURCES = "tools/translation/sources/"

    private fun sources(folder: File): List<File> = folder.listFiles { f -> CacheTranslationPatch.SOURCE_PREFIXES.any { f.name.startsWith(it) } && f.name.endsWith(".json") }!!.sortedBy { it.name }

    private fun quote(value: String): String {
        check('\\' !in value && '\n' !in value) { "Unsupported character in '$value'." }
        return "\"" + value.replace("\"", "\\\"") + "\""
    }

    /** Writes the table from the translation sources, failing if a text in scope is missing or a source is unused */
    fun writeTable(source: Source, out: File, folder: File = File(SOURCES)) {
        val portuguese = mutableMapOf<String, String>()
        for (file in sources(folder)) {
            val map: Map<String, String> = jacksonObjectMapper().readValue(file)
            for ((en, pt) in map) {
                val previous = portuguese.put(en, pt)
                check(previous == null || previous == pt) { "Two translations of '$en' in ${file.name}: '$previous' and '$pt'." }
            }
        }
        val inScope = CacheTranslationPatch.texts(source, all = false).map { it.english }.toSet()
        val lines = mutableListOf(
            "# Brazilian Portuguese for the interfaces the client draws from the cache (Task System, level up pop-up),",
            "# generated by `./gradlew :tools:translateInterfaces --args=table` from tools/translation/sources/pt_tasks*.json",
            "# and pt_level_up*.json: edit those, not this file. The cache copy is applied with `--args=patch`; the server uses",
            "# the name, difficulty, area and chat rows in task chat messages and sends the label rows itself.",
            "",
            "[interface_pt_br]",
            "en = \"string\"",
            "pt = \"string\"",
            "interface = \"int\"",
            "component = \"int\"",
        )
        val missing = mutableListOf<String>()
        val used = mutableSetOf<String>()
        for (text in CacheTranslationPatch.texts(source)) {
            val pt = portuguese[text.english]
            if (pt == null) {
                if (text.english in inScope) {
                    missing.add("${text.row}: ${text.english}")
                }
                continue
            }
            used.add(text.english)
            val bad = pt.filter { it.code !in 0x20..0xff }
            check(bad.isEmpty()) { "Characters the client can't show in '$pt': $bad" }
            check(pt.toByteArray().size <= 500) { "Over 500 bytes: '$pt'" }
            lines += ""
            lines += "[.${text.row}]"
            lines += "en = ${quote(text.english)}"
            lines += "pt = ${quote(pt)}"
            if (text.kind == "label") {
                val (id, component) = text.row.removePrefix("label_").split("_").map { it.toInt() }
                lines += "interface = $id"
                lines += "component = $component"
            }
        }
        val unused = portuguese.keys - used
        if (missing.isNotEmpty() || unused.isNotEmpty()) {
            System.err.println("Missing:\n" + missing.joinToString("\n"))
            System.err.println("Unused:\n" + unused.joinToString("\n"))
            exitProcess(1)
        }
        out.writeText(lines.joinToString("\n") + "\n", Charsets.UTF_8)
        println("${used.size} translations written to $out")
    }

    private fun guideSources(folder: File): List<File> = folder.listFiles { f -> f.name.startsWith(SkillGuideTranslation.SOURCE_PREFIX) && f.name.endsWith(".json") }!!.sortedBy { it.name }

    /**
     * Writes the skill guide's table from the pt_guide sources. The guide is translated in parts, so texts without
     * Portuguese are only counted (they stay in English); a translation of a text the guide no longer has fails.
     * It's kept out of the server's tables (the `.guide.toml` extension): only the cache needs it.
     */
    fun writeGuideTable(source: Source, out: File, folder: File = File(SOURCES)) {
        val portuguese = mutableMapOf<String, String>()
        for (file in guideSources(folder)) {
            val map: Map<String, String> = jacksonObjectMapper().readValue(file)
            for ((en, pt) in map) {
                val previous = portuguese.put(en, pt)
                check(previous == null || previous == pt) { "Two translations of '$en' in ${file.name}: '$previous' and '$pt'." }
            }
        }
        val lines = mutableListOf(
            "# Brazilian Portuguese for the Skill Advance Guide and the level up pop-up's list of unlocks, generated by",
            "# `./gradlew :tools:translateInterfaces --args=table` from tools/translation/sources/pt_guide*.json: edit those,",
            "# not this file. Only the cache uses it (`--args=patch`), so the server doesn't load it.",
            "",
            "[skill_guide_pt_br]",
            "en = \"string\"",
            "pt = \"string\"",
        )
        val used = mutableSetOf<String>()
        var missing = 0
        for ((i, text) in SkillGuideTranslation.texts(source).withIndex()) {
            val english = text.second
            val pt = portuguese[english]
            if (pt == null) {
                missing++
                continue
            }
            used.add(english)
            val bad = pt.filter { it.code !in 0x20..0xff }
            check(bad.isEmpty()) { "Characters the client can't show in '$pt': $bad" }
            lines += ""
            lines += "[.guide_${text.first}_$i]"
            lines += "en = ${quote(english)}"
            lines += "pt = ${quote(pt)}"
        }
        val unused = portuguese.keys - used
        if (unused.isNotEmpty()) {
            System.err.println("Unused:\n" + unused.joinToString("\n"))
            exitProcess(1)
        }
        out.writeText(lines.joinToString("\n") + "\n", Charsets.UTF_8)
        println("${used.size} skill guide translations written to $out, $missing texts left in English")
    }

    /** Lists the English texts in scope without a translation in the format of tools/translation/validate.py */
    fun dump(source: Source, folder: File = File(SOURCES)) {
        val translated = sources(folder).flatMap { jacksonObjectMapper().readValue<Map<String, String>>(it).keys }.toSet()
        val missing = CacheTranslationPatch.texts(source, all = false).filter { it.english !in translated }
            .groupBy({ it.kind }, { mapOf("kind" to it.kind, "en" to it.english) })
            .toMutableMap()
        val guideTranslated = guideSources(folder).flatMap { jacksonObjectMapper().readValue<Map<String, String>>(it).keys }.toSet()
        val guide = SkillGuideTranslation.texts(source).filter { it.second !in guideTranslated }.map { mapOf("kind" to "guide_${it.first}", "en" to it.second) }
        if (guide.isNotEmpty()) {
            missing["guide"] = guide
        }
        jacksonObjectMapper().writerWithDefaultPrettyPrinter().writeValue(folder.resolve("missing_interfaces.json"), missing)
        println("${missing.values.sumOf { it.size }} untranslated texts written to ${folder.resolve("missing_interfaces.json")}")
    }

    fun apply(library: CacheLibrary, source: Source, patch: CacheTranslationPatch.Patch) {
        for ((id, script) in patch.scripts) {
            val data = CacheTranslationPatch.encode(script)
            if (!data.contentEquals(source.scriptBytes(id))) {
                library.put(Index.CLIENT_SCRIPTS, id, data)
            }
        }
        for ((id, enum) in patch.enums) {
            val data = CacheTranslationPatch.encode(enum)
            if (!data.contentEquals(source.enumBytes(id))) {
                library.put(Index.ENUMS, id ushr 8, id and 0xff, data)
            }
        }
        for (id in patch.removeScripts) {
            library.remove(Index.CLIENT_SCRIPTS, id)
        }
        for (id in patch.removeEnums) {
            library.remove(Index.ENUMS, id ushr 8, id and 0xff)
        }
        library.update()
    }

    @JvmStatic
    fun main(args: Array<String>) {
        val mode = args.firstOrNull() ?: "patch"
        val path = args.indexOf("--cache").takeIf { it != -1 }?.let { args[it + 1] } ?: "./data/cache/"
        val table = File(args.indexOf("--table").takeIf { it != -1 }?.let { args[it + 1] } ?: CacheTranslationPatch.TABLE_PATH)
        val guideTable = File(args.indexOf("--guide-table").takeIf { it != -1 }?.let { args[it + 1] } ?: SkillGuideTranslation.TABLE_PATH)
        val library = CacheLibrary(path)
        val source = Source(CacheDelegate(library))
        when (mode) {
            "dump" -> dump(source)
            "table" -> {
                writeTable(source, table)
                writeGuideTable(source, guideTable)
            }
            "patch" -> {
                if (path == "./data/cache/" && !portFree(43594)) {
                    System.err.println("The game server is running: stop it before changing the cache it serves.")
                    exitProcess(1)
                }
                val guide = if (guideTable.exists()) CacheTranslationPatch.readTable(guideTable) else emptyList()
                val patch = CacheTranslationPatch.patch(source, CacheTranslationPatch.readTable(table), guide)
                val differences = CacheTranslationPatch.differences(source, patch)
                if (differences.isEmpty()) {
                    println("Cache already up to date.")
                    return
                }
                apply(library, source, patch)
                println("Updated ${differences.size} cache files: ${differences.joinToString()}")
            }
            else -> {
                System.err.println("Unknown mode '$mode', expected dump, table or patch.")
                exitProcess(1)
            }
        }
    }

    private fun portFree(port: Int): Boolean = try {
        ServerSocket(port).close()
        true
    } catch (e: Exception) {
        false
    }
}
